int copy_creds(struct task_struct *p, unsigned long clone_flags) {
    struct cred *new;

    if ((clone_flags & CLONE_NEWPID) && (clone_flags & CLONE_THREAD)) {
        return 0; // Share credentials with parent
    }

    get_cred(p->cred); // Increment reference count of existing credentials

    if ((clone_flags & CLONE_NEWUSER) ||
        (clone_flags & CLONE_NEWPID) ||
        (clone_flags & CLONE_NEWNET)) {
        new = prepare_creds();
        if (!new)
            return -ENOMEM;

        if ((clone_flags & CLONE_NEWUSER))
            new->user_ns = create_user_ns(new);
        if (!new->user_ns)
            return -ENOMEM;

        p->cred = new;
    }

    if ((clone_flags & CLONE_THREAD)) {
        p->thread_keyring = NULL;
        p->session_keyring = NULL;
    }

    return 0;
}

int copy_creds(struct task_struct *p, unsigned long clone_flags) {
    struct cred *new;

    if ((clone_flags & CLONE_THREAD) && (p->cred->magic != 0)) {
        if (!atomic_inc_not_zero(&p->cred->usage)) {
            return -ENOMEM;
        }
        return 0;
    }

    new = prepare_creds();
    if (new == NULL) {
        return -ENOMEM;
    }

    if (clone_flags & CLONE_NEWUSER) {
        struct user_namespace *ns;

        ns = create_user_namespace(p->cred);
        if (IS_ERR(ns)) {
            abort_creds(new);
            return PTR_ERR(ns);
        }
        new->user_ns = ns;
    }

    if (clone_flags & CLONE_THREAD) {
        new->tgcred = get_tgcred(p->cred);
        new->thread_keyring = p->thread_keyring;
        if (new->thread_keyring) {
            key_get(new->thread_keyring);
        }
    }

    if (clone_flags & CLONE_NEWPID) {
        new->pid_keyring = NULL;
    }

    if (clone_flags & CLONE_NEWSESSION) {
        new->session_keyring = NULL;
    }

    if (copy_creds_pre(new, p->cred) < 0) {
        abort_creds(new);
        return -ENOMEM;
    }

    p->cred = new;

    return 0;
}

int copy_credentials(struct task_struct *p, unsigned long clone_flags)
{
    struct cred *new, *old;

    old = p->cred;
    if (clone_flags & CLONE_SHARE_CREDENTIALS) {
        get_cred(old);
        p->cred = old;
        return 0;
    }

    new = prepare_creds();
    if (!new)
        return -ENOMEM;

    if (clone_flags & CLONE_NEWUSER) {
        int ret = create_user_ns(new);
        if (ret < 0) {
            abort_creds(new);
            return ret;
        }
    }

    if (clone_flags & CLONE_THREAD) {
        new->thread_keyring = NULL;
    } else {
        if (old->process_keyring)
            key_get(old->process_keyring);
        if (old->session_keyring)
            key_get(old->session_keyring);
    }

    p->cred = new;
    return 0;
}

#include <linux/cred.h>
#include <linux/key.h>
#include <linux/slab.h>
#include <linux/errno.h>

int copy_creds_for_task(struct task_struct *p, unsigned long clone_flags)
{
    int ret = 0;

    if (clone_flags & CLONE_NEWUSER) {
        struct cred *new_cred = prepare_creds();
        if (!new_cred)
            return -ENOMEM;

        /* Handle user namespace creation and cred setup if needed */
        ret = setup_new_userns(p, new_cred, clone_flags);
        if (ret)
            return ret;

        p->real_cred = p->cred = get_cred(new_cred);
        return 0;
    } else {
        // Share credentials
        get_cred(p->cred);
        get_cred(p->real_cred);
    }

    // Manage keyrings according to thread sharing rules
    if (clone_flags & CLONE_THREAD) {
        key_get(p->thread_keyring);
        key_get(p->session_keyring);
    } else {
        key_put(p->thread_keyring);
        key_put(p->session_keyring);
        p->thread_keyring = NULL;
        p->session_keyring = NULL;
    }

    return 0;
}
